let marketData=[],lastTrades=[],lastEquity=[];
const bt=s=>document.querySelector(s),btAll=s=>[...document.querySelectorAll(s)];
function showBacktest(){bt('.canvas').classList.add('hidden');bt('#codePanel').classList.add('hidden');bt('#backtestPanel').classList.remove('hidden');btAll('.tabs button').forEach(x=>x.classList.remove('active'));bt('#backtestTab').classList.add('active')}
bt('#backtestTab').addEventListener('click',showBacktest);btAll('.tabs button')[0].addEventListener('click',()=>bt('#backtestPanel').classList.add('hidden'));bt('#codeTab').addEventListener('click',()=>bt('#backtestPanel').classList.add('hidden'));
function normalizeRow(row,i){const lower={};Object.keys(row).forEach(k=>lower[k.trim().toLowerCase()]=row[k]);const close=Number(lower.close||lower.cierre);if(!Number.isFinite(close)||close<=0)return null;return{date:String(lower.date||lower.datetime||lower.fecha||i+1),open:Number(lower.open||lower.apertura||close),high:Number(lower.high||lower.max||close),low:Number(lower.low||lower.min||close),close,volume:Number(lower.volume||lower.volumen||0)}}
function parseCSV(text){const lines=text.trim().split(/\r?\n/).filter(Boolean);if(lines.length<3)throw new Error('El CSV necesita encabezados y al menos dos filas.');const sep=lines[0].includes(';')?';':',';const headers=lines[0].split(sep).map(x=>x.trim().replace(/^"|"$/g,''));return lines.slice(1).map((line,i)=>{const values=line.split(sep).map(x=>x.trim().replace(/^"|"$/g,'')),row={};headers.forEach((h,j)=>row[h]=values[j]);return normalizeRow(row,i)}).filter(Boolean)}
function generateDemo(){const rows=[];let price=100,date=new Date('2022-01-03');for(let i=0;i<760;i++){const cycle=Math.sin(i/34)*.008+Math.sin(i/91)*.004,trend=i<230?.0007:i<410?-.0005:i<610?.0009:-.00015,noise=Math.sin(i*1.71)*.006;const open=price,close=Math.max(8,price*(1+cycle+trend+noise));rows.push({date:date.toISOString().slice(0,10),open,high:Math.max(open,close)*1.006,low:Math.min(open,close)*.994,close,volume:1000000+Math.round(Math.abs(noise)*8e7)});price=close;date.setDate(date.getDate()+1)}return rows}
function setDataset(rows,name){marketData=rows;bt('#datasetName').textContent=name;bt('#datasetRows').textContent=`${rows.length.toLocaleString('es-AR')} velas`;bt('#datasetRange').textContent=rows.length?`${rows[0].date} → ${rows.at(-1).date}`:'—';bt('#dataDot').classList.toggle('ready',rows.length>0);drawEquity(rows.slice(-120).map((r,i)=>({date:r.date,value:r.close})),true)}
bt('#demoData').onclick=()=>{setDataset(generateDemo(),'Dataset demo · SBS Synthetic');toast('Datos demo cargados')};bt('#csvInput').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const rows=parseCSV(await file.text());if(rows.length<210)throw new Error('Se recomiendan al menos 210 velas para SMA 200.');setDataset(rows,file.name);toast('CSV validado y cargado')}catch(err){toast(err.message);e.target.value=''}};
function sma(values,p,i){if(i<p-1)return null;let sum=0;for(let j=i-p+1;j<=i;j++)sum+=values[j];return sum/p}
function rsi(values,p,i){if(i<p)return null;let gain=0,loss=0;for(let j=i-p+1;j<=i;j++){const d=values[j]-values[j-1];if(d>0)gain+=d;else loss-=d}if(loss===0)return 100;const rs=(gain/p)/(loss/p);return 100-(100/(1+rs))}
function simulate(){if(marketData.length<210){toast('Cargá datos demo o un CSV con al menos 210 velas');return}const panel=bt('#backtestPanel');panel.classList.add('running');setTimeout(()=>{const closes=marketData.map(x=>x.close),initial=+bt('#cash').value||10000,commission=(+bt('#commission').value||0)/100,size=(+bt('#size').value||95)/100,stop=(+state.exit.find(x=>x.left==='Pérdida')?.value||2)/100,target=(+state.exit.find(x=>x.left==='Ganancia')?.value||5)/100;let cash=initial,position=0,entry=0,entryDate='',peak=initial,maxDD=0;const equity=[],trades=[];for(let i=200;i<marketData.length;i++){const fast=sma(closes,50,i),slow=sma(closes,200,i),prevFast=sma(closes,50,i-1),prevSlow=sma(closes,200,i-1),momentum=rsi(closes,14,i),price=closes[i];if(!position&&prevFast<=prevSlow&&fast>slow&&momentum<70){const allocation=cash*size,fee=allocation*commission;position=(allocation-fee)/price;cash-=allocation;entry=price;entryDate=marketData[i].date}else if(position){let reason='';if(prevFast>=prevSlow&&fast<slow)reason='Cruce bajista';else if(price<=entry*(1-stop))reason='Stop loss';else if(price>=entry*(1+target))reason='Take profit';if(reason){const gross=position*price,fee=gross*commission,pnl=gross-fee-(position*entry);cash+=gross-fee;trades.push({entryDate,exitDate:marketData[i].date,entry,exit:price,pnl,reason});position=0}}const value=cash+position*price;peak=Math.max(peak,value);maxDD=Math.max(maxDD,(peak-value)/peak);equity.push({date:marketData[i].date,value})}if(position){const r=marketData.at(-1),gross=position*r.close,fee=gross*commission,pnl=gross-fee-(position*entry);cash+=gross-fee;trades.push({entryDate,exitDate:r.date,entry,exit:r.close,pnl,reason:'Fin de datos'});equity.at(-1).value=cash}lastTrades=trades;lastEquity=equity;renderResults(initial,cash,maxDD,trades,equity);panel.classList.remove('running')},120)}
function renderResults(initial,final,maxDD,trades,equity){const ret=(final/initial-1)*100,wins=trades.filter(t=>t.pnl>0),losses=trades.filter(t=>t.pnl<=0),winrate=trades.length?wins.length/trades.length*100:0,gain=wins.reduce((s,t)=>s+t.pnl,0),loss=Math.abs(losses.reduce((s,t)=>s+t.pnl,0)),pf=loss?gain/loss:(gain?Infinity:0);bt('#metricReturn').textContent=`${ret>=0?'+':''}${ret.toFixed(2)}%`;bt('#metricReturn').className=ret>=0?'positive':'negative';bt('#metricPnl').textContent=`${(final-initial).toLocaleString('es-AR',{style:'currency',currency:'USD'})}`;bt('#metricDrawdown').textContent=`-${(maxDD*100).toFixed(2)}%`;bt('#metricWinrate').textContent=`${winrate.toFixed(1)}%`;bt('#metricTrades').textContent=`${trades.length} operaciones`;bt('#metricPF').textContent=Number.isFinite(pf)?pf.toFixed(2):'∞';bt('#chartLegend').textContent=`${initial.toLocaleString('es-AR',{style:'currency',currency:'USD'})} → ${final.toLocaleString('es-AR',{style:'currency',currency:'USD'})}`;bt('#tradesBody').innerHTML=trades.length?trades.map((t,i)=>`<tr><td>${i+1}</td><td>${t.entryDate}</td><td>${t.exitDate}</td><td>$${t.entry.toFixed(2)}</td><td>$${t.exit.toFixed(2)}</td><td class="${t.pnl>=0?'win':'loss'}">${t.pnl>=0?'+':''}$${t.pnl.toFixed(2)}</td><td>${t.reason}</td></tr>`).join(''):'<tr><td colspan="7" class="empty-row">No hubo señales con estos datos.</td></tr>';bt('#downloadTrades').disabled=!trades.length;drawEquity(equity,false);toast('Backtest completado')}
function drawEquity(points,preview){const c=bt('#equityChart'),ctx=c.getContext('2d'),dpr=window.devicePixelRatio||1,w=c.clientWidth||900,h=c.clientHeight||280;c.width=w*dpr;c.height=h*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);if(points.length<2)return;const vals=points.map(x=>x.value),min=Math.min(...vals),max=Math.max(...vals),pad=Math.max((max-min)*.15,1),lo=min-pad,hi=max+pad,x=i=>24+i*(w-48)/(points.length-1),y=v=>18+(hi-v)*(h-38)/(hi-lo);ctx.strokeStyle='#e9efef';ctx.lineWidth=1;for(let i=1;i<5;i++){const yy=i*h/5;ctx.beginPath();ctx.moveTo(18,yy);ctx.lineTo(w-18,yy);ctx.stroke()}const grad=ctx.createLinearGradient(0,0,0,h);grad.addColorStop(0,preview?'rgba(120,150,155,.2)':'rgba(49,211,167,.25)');grad.addColorStop(1,'rgba(49,211,167,0)');ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(x(i),y(p.value)):ctx.moveTo(x(i),y(p.value)));ctx.lineTo(x(points.length-1),h-18);ctx.lineTo(x(0),h-18);ctx.closePath();ctx.fillStyle=grad;ctx.fill();ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(x(i),y(p.value)):ctx.moveTo(x(i),y(p.value)));ctx.strokeStyle=preview?'#91a5a8':'#22b98f';ctx.lineWidth=2;ctx.stroke()}
bt('#runBacktest').onclick=simulate;bt('#downloadTrades').onclick=()=>{const csv='entry_date,exit_date,entry_price,exit_price,pnl,reason\n'+lastTrades.map(t=>`${t.entryDate},${t.exitDate},${t.entry.toFixed(4)},${t.exit.toFixed(4)},${t.pnl.toFixed(4)},${t.reason}`).join('\n');downloadText(csv,'text/csv',pyName()+'-trades.csv')};window.addEventListener('resize',()=>{if(lastEquity.length)drawEquity(lastEquity,false)});

